SELECT n.id AS id, n.user_id AS userId, n.express_id AS expressId, e.express_no AS expressNo, n.title AS title, n.content AS content, n.type AS type, n.is_read AS isRead, DATE_FORMAT(n.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(n.read_time, '%Y-%m-%d %H:%i:%s') AS readTime FROM notification n LEFT JOIN express e ON e.id = n.express_id AND e.deleted = 0 WHERE n.user_id = #{userId}
AND n.is_read = #{isRead}
AND n.type = #{type}
ORDER BY n.id DESC

SELECT n.id AS id, n.user_id AS userId, n.express_id AS expressId, e.express_no AS expressNo, n.title AS title, n.content AS content, n.type AS type, n.is_read AS isRead, DATE_FORMAT(n.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(n.read_time, '%Y-%m-%d %H:%i:%s') AS readTime FROM notification n LEFT JOIN express e ON e.id = n.express_id AND e.deleted = 0 WHERE 1 = 1
AND n.user_id = #{userId}
AND n.type = #{type}
ORDER BY n.id DESC

